const stdout = $input.first().json.stdout || '';

const metaBlock = stdout.split('===META===')[1]?.split('===VTT===')[0]?.trim() || '';
const vttBlock = stdout.split('===VTT===')[1]?.split('===END===')[0]?.trim() || '';

let meta = {};
try {
  // yt-dlp --dump-json prints one JSON object per line (per video); use the first.
  const firstLine = metaBlock.split('\n')[0];
  meta = firstLine ? JSON.parse(firstLine) : {};
} catch (e) {
  meta = {};
}

function vttToText(vtt) {
  if (!vtt) return '';
  const out = [];
  let lastLine = null;
  for (const raw of vtt.split('\n')) {
    let line = raw.trim();
    if (!line || line === 'WEBVTT' || line.includes('-->') || /^\d+$/.test(line)) continue;
    line = line.replace(/<[^>]+>/g, '').trim();
    if (!line || line === lastLine) continue;
    out.push(line);
    lastLine = line;
  }
  return out.join('\n');
}

const transcript = vttToText(vttBlock);
const videoInput = $('Video Input').item.json;

return [{
  json: {
    videoUrl: videoInput.videoUrl,
    vaultPath: videoInput.vaultPath,
    folder: videoInput.folder,
    title: meta.title || 'Untitled Video',
    channel: meta.uploader || meta.channel || 'Unknown',
    uploadDate: meta.upload_date || '',
    duration: meta.duration || null,
    transcript: transcript || '(No transcript could be extracted automatically - paste it manually and re-run from here.)',
  },
}];

const parsed = $('Parse Transcript').item.json;
const summaryMarkdown = $json.text || '(summary unavailable)';

const dateWatched = $now.toFormat('yyyy-LL-dd');

function sanitize(title) {
  return (title || 'Untitled Video')
    .replace(/[\\/:*?"<>|]/g, '-')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 150);
}

const safeTitle = sanitize(parsed.title);
const platform = parsed.videoUrl.includes('skool.com')
  ? 'Skool'
  : (parsed.videoUrl.includes('youtu') ? 'YouTube' : 'Video');

const frontmatter = `---
title: "${parsed.title}"
source: ${parsed.videoUrl}
platform: ${platform}
creator: ${parsed.channel}
date_watched: ${dateWatched}
tags: [video-notes, ${platform.toLowerCase()}]
---`;

const noteContent = `${frontmatter}

# ${parsed.title}

**Source:** [${platform} link](${parsed.videoUrl})
**Creator:** ${parsed.channel}
**Date watched:** ${dateWatched}

${summaryMarkdown}

## Full Transcript

<details>
<summary>Click to expand transcript</summary>

${parsed.transcript}

</details>
`;

return [{
  json: {
    noteContent,
    fileName: safeTitle,
    vaultPath: parsed.vaultPath,
    folder: parsed.folder,
  },
}];
